(function() {
    'use strict';

    class ServiceThatSellsAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Service That Sells`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Maharlika Bank).
            this.START_SAT = 69;        // customer satisfaction top-2-box (%)
            this.TARGET_SAT = 75;       // board recovery target (%)
            this.FLOOR_SAT = 65;        // below this, the board pivots to price
            this.START_GAP = 1.8;       // SERVQUAL service-quality gap (points, lower better)
            this.START_BRAND = 58;      // brand-equity index
            this.BUDGET = 600;          // ₱600M fixed, allocate three ways
            this.ATTRITION_PT = 410;    // ₱410M lost lifetime revenue per annual attrition point
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    sat: this.START_SAT,            // customer satisfaction (%)
                    gap: this.START_GAP,            // service-quality gap (points)
                    brand: this.START_BRAND,        // brand-equity index
                    roi: 0,                         // marketing ROI (×)
                    engagement: 61,                 // front-line engagement (%)
                    promise: 15,                    // advertised service standard (minutes)
                    actualTime: 34,                 // actual average branch service time (minutes)
                    spent: 0,                        // ₱M committed of the ₱600M
                    internalSpent: 0,               // ₱M committed to internal marketing
                    adSpent: 0,                     // ₱M committed to external advertising
                    serviceSpent: 0,                // ₱M committed to customer-facing service
                    pendingSatLift: 0,              // satisfaction improvement queued by lag (lands next round)
                    // Sticky, run-defining penalty flags (set when an error is committed).
                    overPromiseRun: false,          // advertising a promise the operation cannot keep
                    adFixRun: false,                // advertising-led while internal root cause under-funded
                    misdiagnosed: false,            // located the cause anywhere but internal service
                    slaUnresourced: false,          // mandated an SLA with no capacity/recognition
                    overBudget: false,              // committed more than ₱600M
                    satHistory: [this.START_SAT],
                    brandHistory: [this.START_BRAND],
                    gapHistory: [this.START_GAP],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors (advertising the fix,
                // front-line-as-cure, keep the 15-min promise) — a blind click-through must NOT win.
                state.decisions = {
                    root: `frontline`,
                    dim: `empathy`,
                    symptom: `both_symptom`,
                    inaction: 30,
                    sla: `mandate`,
                    empower: `none`,
                    culture: `orders`,
                    internalBudget: 40,
                    promise: `15`,
                    advertising: `350`,
                    service: `80`,
                    internalTopup: 0,
                    defense: `ads`,
                    shock: `neobank`,
                    indicator: `awareness`,
                    hold: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ro = document.getElementById(`rootInput`);
                const di = document.getElementById(`dimInput`);
                const sy = document.getElementById(`symptomInput`);
                const ia = document.getElementById(`inactionInput`);
                if (ro) decisions.root = ro.value;
                if (di) decisions.dim = di.value;
                if (sy) decisions.symptom = sy.value;
                if (ia) decisions.inaction = parseInt(ia.value, 10);
                if (!Number.isFinite(decisions.inaction) || decisions.inaction < 0 || decisions.inaction > 100) {
                    warn(`warn_inaction_range`); return false;
                }
            } else if (round === 2) {
                const sl = document.getElementById(`slaInput`);
                const em = document.getElementById(`empowerInput`);
                const cu = document.getElementById(`cultureInput`);
                const ib = document.getElementById(`internalBudgetInput`);
                if (sl) decisions.sla = sl.value;
                if (em) decisions.empower = em.value;
                if (cu) decisions.culture = cu.value;
                if (ib) decisions.internalBudget = parseFloat(ib.value);
                if (!Number.isFinite(decisions.internalBudget) || decisions.internalBudget < 0 || decisions.internalBudget > 300) {
                    warn(`warn_internalbudget_range`); return false;
                }
            } else if (round === 3) {
                const pr = document.getElementById(`promiseInput`);
                const ad = document.getElementById(`advertisingInput`);
                const sv = document.getElementById(`serviceInput`);
                const tu = document.getElementById(`internalTopupInput`);
                if (pr) decisions.promise = pr.value;
                if (ad) decisions.advertising = ad.value;
                if (sv) decisions.service = sv.value;
                if (tu) decisions.internalTopup = parseFloat(tu.value);
                if (!Number.isFinite(decisions.internalTopup) || decisions.internalTopup < 0 || decisions.internalTopup > 300) {
                    warn(`warn_topup_range`); return false;
                }
                // Budget guard: Round 2 internal + this round's three slices + top-up must fit ₱600M.
                const ds = state.domainState;
                const total = (ds ? ds.internalSpent : 0)
                    + parseFloat(decisions.advertising)
                    + parseFloat(decisions.service)
                    + (Number.isFinite(decisions.internalTopup) ? decisions.internalTopup : 0);
                if (total > this.BUDGET) {
                    warn(`warn_overbudget`); return false;
                }
            } else if (round === 4) {
                const de = document.getElementById(`defenseInput`);
                const sh = document.getElementById(`shockInput`);
                const ind = document.getElementById(`indicatorInput`);
                const ho = document.getElementById(`holdInput`);
                if (de) decisions.defense = de.value;
                if (sh) decisions.shock = sh.value;
                if (ind) decisions.indicator = ind.value;
                if (ho) decisions.hold = parseInt(ho.value, 10);
                if (!Number.isFinite(decisions.hold) || decisions.hold < 0 || decisions.hold > 100) {
                    warn(`warn_hold_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let satDelta = 0, gapDelta = 0, brandDelta = 0, engageDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            // Lagged satisfaction lift queued from a previous round lands now.
            const arriving = ds.pendingSatLift || 0;
            satDelta += arriving;
            ds.pendingSatLift = 0;

            if (round === 1) {
                // Diagnose the gap (Common Error 2: treating it as a front-line problem).
                switch (d.root) {
                    case `internal`:
                        gapDelta -= 0.1; engageDelta += 1; coachKey = `coach_r1_internal`; break;
                    case `frontline`:
                        ds.misdiagnosed = true; gapDelta += 0.1; coachKey = `coach_r1_frontline`; break;
                    case `advertising`:
                        ds.misdiagnosed = true; ds.adFixRun = true; gapDelta += 0.1; coachKey = `coach_r1_advertising`; break;
                    case `customers`:
                        ds.misdiagnosed = true; gapDelta += 0.1; coachKey = `coach_r1_customers`; break;
                }

                switch (d.dim) {
                    case `reliability_resp`: gapDelta -= 0.1; if (d.root === `internal`) coachKey = `coach_r1_sharp`; break;
                    case `tangibles`: gapDelta += 0.05; coachKey = `coach_r1_tangibles`; break;
                    case `empathy`: gapDelta += 0.05; coachKey = `coach_r1_empathy`; break;
                    case `assurance`: gapDelta += 0.05; break;
                }

                switch (d.symptom) {
                    case `cause_chain`: brandDelta += 1; engageDelta += 1; break;
                    case `both_symptom`: ds.misdiagnosed = true; coachKey = `coach_r1_symptomboth`; break;
                    case `cause_ads`: ds.misdiagnosed = true; ds.adFixRun = true; coachKey = `coach_r1_symptomads`; break;
                }

                // Sizing the cost of inaction = how well the board is prepared for the lag.
                if (d.inaction >= 60) { brandDelta += 1; }
                else if (d.inaction <= 20) { coachKey = (coachKey === `coach_default`) ? `coach_r1_inaction` : coachKey; }

                summaryKey = (d.root === `internal` && d.dim === `reliability_resp` && d.symptom === `cause_chain`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Build internal marketing orientation (Common Error 3: SLAs without internal marketing).
                ds.internalSpent = Math.min(300, Math.round((ds.internalSpent + d.internalBudget) * 10) / 10);

                // Internal SLA standard.
                switch (d.sla) {
                    case `resourced`: ds.gap -= 0; gapDelta -= 0.2; engageDelta += 6; break;
                    case `mandate`: ds.slaUnresourced = true; engageDelta -= 3; gapDelta += 0.1; coachKey = `coach_r2_mandate`; break;
                    case `none`: engageDelta -= 5; gapDelta += 0.15; coachKey = `coach_r2_nosla`; break;
                }

                // Front-line empowerment / service-recovery paradox.
                switch (d.empower) {
                    case `capped`: gapDelta -= 0.2; engageDelta += 5; brandDelta += 1; break;
                    case `none`: gapDelta += 0.1; engageDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r2_noempower` : coachKey; break;
                    case `unlimited`: gapDelta += 0.05; engageDelta += 1; coachKey = `coach_r2_unlimited`; break;
                }

                // Make internal departments WANT to serve — culture, not just contract.
                switch (d.culture) {
                    case `market`: engageDelta += 7; gapDelta -= 0.2; if (d.sla === `resourced` && d.empower === `capped`) coachKey = `coach_r2_orientation`; break;
                    case `orders`: ds.slaUnresourced = true; engageDelta -= 3; coachKey = `coach_r2_orders`; break;
                    case `ignore`: engageDelta -= 4; coachKey = `coach_r2_ignoreculture`; break;
                }

                // Internal marketing has a LAG: most of the effect lands next round (service-profit chain).
                // Effect size scales with how much you funded the root cause AND whether it was resourced + cultural.
                const fundFactor = Math.min(1, ds.internalSpent / 120);     // ~₱120M funds the root fix well
                const qualityFactor = (d.sla === `resourced` ? 1 : (d.sla === `mandate` ? 0.35 : 0))
                                    * (d.culture === `market` ? 1 : 0.4);
                const internalLift = Math.round((6.5 * fundFactor * Math.max(0.3, qualityFactor)) * 10) / 10;
                ds.pendingSatLift += internalLift;                          // lands in Round 3
                // A small immediate engagement-driven taste this round.
                satDelta += Math.round(internalLift * 0.25 * 10) / 10;
                // Internal fix narrows the actual service time too.
                if (d.sla === `resourced` && d.culture === `market`) { ds.actualTime = Math.max(18, ds.actualTime - 8); }
                else if (d.sla !== `none`) { ds.actualTime = Math.max(20, ds.actualTime - 3); }

                summaryKey = (d.sla === `resourced` && d.empower === `capped` && d.culture === `market`) ? `sum_r2_good` :
                             (ds.slaUnresourced ? `sum_r2_unresourced` : `sum_r2_weak`);
            } else if (round === 3) {
                // Allocate the ₱600M and re-set the brand promise (Common Errors 1 & 4, decision tree #1, #4, #6).
                const adv = parseFloat(d.advertising);
                const svc = parseFloat(d.service);
                const top = Number.isFinite(d.internalTopup) ? d.internalTopup : 0;
                ds.adSpent = adv;
                ds.serviceSpent = svc;
                ds.internalSpent = Math.min(400, Math.round((ds.internalSpent + top) * 10) / 10);

                // Re-set the advertised promise.
                const newPromise = parseInt(d.promise, 10);
                ds.promise = newPromise;

                // Customer-facing service investment narrows the actual service time and the gap.
                if (svc >= 300) { ds.actualTime = Math.max(15, ds.actualTime - 9); gapDelta -= 0.35; }
                else if (svc >= 180) { ds.actualTime = Math.max(18, ds.actualTime - 6); gapDelta -= 0.25; }
                else { ds.actualTime = Math.max(20, ds.actualTime - 2); gapDelta -= 0.08; }

                // The brand-promise gap: how much longer the operation actually takes than it promises.
                // Positive = you advertise a faster standard than you can deliver = over-promise (disappointment).
                const promiseGap = ds.actualTime - ds.promise;   // negative/zero = a promise you can keep
                if (promiseGap > 0) {
                    // Advertising a standard faster than the operation can deliver = over-promise. STICKY.
                    ds.overPromiseRun = true;
                    const severity = Math.min(3, 1 + promiseGap / 8);
                    satDelta -= 4 * severity;
                    brandDelta -= 5 * severity;
                    gapDelta += 0.25 * severity;
                    coachKey = `coach_r3_overpromise`;
                } else {
                    // A kept, credible promise (you deliver at or faster than you advertise) builds equity.
                    brandDelta += 5;
                    gapDelta -= 0.2;
                    satDelta += 2;
                }

                // Advertising effect: share-of-voice helps brand ONLY when the operation can keep the promise.
                if (adv >= 350) {
                    if (ds.overPromiseRun || ds.actualTime > ds.promise) {
                        // Advertising the fix — the louder the ad, the more new customers meet the gap.
                        ds.adFixRun = true;
                        satDelta -= 6; brandDelta -= 4; coachKey = `coach_r3_adfix`;
                    } else {
                        brandDelta += 6; satDelta -= 1;   // big spend, but starves the root fix
                    }
                    // Big advertising while internal marketing is under-funded is the headline trap.
                    if (ds.internalSpent < 100) { ds.adFixRun = true; }
                } else if (adv >= 180) {
                    brandDelta += (ds.overPromiseRun ? -1 : 4);
                } else {
                    brandDelta += (ds.overPromiseRun ? 0 : 1);
                    // Ceding too much share-of-voice to neobanks costs a little equity.
                    brandDelta -= 1;
                }

                // Even three-way split signals no diagnosis: near-equal slices that fail to
                // under-weight the advertising currently hurting you and under-resource the binding
                // internal-service constraint (decision tree #6). A diagnosis-led plan makes
                // advertising the SMALLEST slice; an indecisive one leaves it level with the others.
                const slices = [adv, svc, ds.internalSpent];
                const sliceSpread = Math.max(...slices) - Math.min(...slices);
                // A diagnosis-led plan makes advertising the SMALLEST slice and over-weights the
                // internal+service fix. Even-split = three near-equal slices where advertising is
                // NOT clearly de-prioritised (it is the largest or tied-largest).
                const adNotSmallest = adv >= Math.max(svc, ds.internalSpent);
                const evenSplit = sliceSpread <= 60 && adNotSmallest && adv >= 160;
                if (evenSplit) {
                    coachKey = `coach_r3_evensplit`;
                    brandDelta -= 3; satDelta -= 3; gapDelta += 0.1;
                }

                // Under-funding the internal root cause keeps the gap open.
                if (ds.internalSpent < 100) { gapDelta += 0.2; satDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r3_underinternal`; }

                // The well-diagnosed allocation: internal-first, credible promise, measured ad, real service spend.
                if (!ds.overPromiseRun && !ds.adFixRun && ds.internalSpent >= 100 && svc >= 180 && adv <= 200) {
                    coachKey = `coach_r3_allocation`;
                }

                summaryKey = (!ds.overPromiseRun && !ds.adFixRun && ds.internalSpent >= 100 && svc >= 180) ? `sum_r3_good` :
                             (ds.adFixRun ? `sum_r3_adfix` :
                             (ds.overPromiseRun ? `sum_r3_overpromise` : `sum_r3_weak`));
            } else if (round === 4) {
                // Defend the plan and absorb the shock (Common Error 5: ignoring the lag).
                switch (d.defense) {
                    case `chain`: brandDelta += 3; satDelta += 1; coachKey = `coach_r4_chain`; break;
                    case `ads`: brandDelta -= 2; coachKey = `coach_r4_defenseads`; break;
                    case `deny`: brandDelta -= 4; satDelta -= 1; coachKey = `coach_r4_deny`; break;
                }

                switch (d.shock) {
                    case `viral`:
                        // Service-recovery paradox: owning it well, behind a kept promise, builds trust.
                        if (!ds.overPromiseRun) { satDelta += 3; brandDelta += 3; }
                        else { satDelta -= 3; brandDelta -= 2; coachKey = `coach_r4_viral_broken`; }
                        break;
                    case `neobank`:
                        // Matching a blitz peso-for-peso abandons the service-led strategy.
                        ds.adFixRun = true; brandDelta -= 3; satDelta -= 2; coachKey = `coach_r4_neobank`; break;
                    case `cfocut`:
                        // Cutting internal marketing re-opens the root cause.
                        ds.internalSpent = Math.max(0, ds.internalSpent - 60);
                        gapDelta += 0.2; satDelta -= 3; engageDelta -= 4; coachKey = `coach_r4_cfocut`; break;
                }

                switch (d.indicator) {
                    case `internal`: brandDelta += 2; if (d.defense === `chain`) coachKey = `coach_r4_indicator`; break;
                    case `awareness`: brandDelta -= 1; coachKey = (coachKey === `coach_default`) ? `coach_r4_awareness` : coachKey; break;
                    case `satisfaction`: coachKey = (coachKey === `coach_default`) ? `coach_r4_lagindicator` : coachKey; break;
                }

                // Conviction to hold through the lag quarter.
                if (d.hold >= 60) { satDelta += 1; brandDelta += 1; }
                else if (d.hold <= 25) { brandDelta -= 2; }

                summaryKey = (d.defense === `chain` && (d.shock === `viral` || d.shock === `cfocut`) && d.indicator === `internal` && !ds.adFixRun) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply deltas (clamped). ----
            ds.engagement = Math.max(0, Math.min(100, Math.round(ds.engagement + engageDelta)));
            ds.gap = Math.max(0, Math.min(3, Math.round((ds.gap + gapDelta) * 100) / 100));
            ds.brand = Math.max(0, Math.min(100, Math.round(ds.brand + brandDelta)));

            // ---- Satisfaction: STICKY error flags cap the ceiling. ----
            ds.sat = Math.round((ds.sat + satDelta) * 10) / 10;
            // The over-promise / advertising-the-fix run gates the top: satisfaction cannot reach
            // the board target while the promise is undeliverable or the spend amplifies the gap.
            let satCeiling = 100;
            if (ds.overPromiseRun || ds.adFixRun) satCeiling = Math.min(satCeiling, this.TARGET_SAT - 1.5); // capped below 75%
            if (ds.misdiagnosed) satCeiling = Math.min(satCeiling, 74);
            ds.sat = Math.max(40, Math.min(satCeiling, ds.sat));

            // ---- Marketing ROI: retained customer value per ₱ committed. ----
            // Satisfaction recovery shrinks attrition; each recovered point of satisfaction maps to
            // attrition recovery worth ~₱410M / point of annual attrition.
            const satGain = Math.max(0, ds.sat - this.START_SAT);          // points recovered
            const attritionRecovered = satGain * 0.09;                     // pts of annual attrition reduced
            const valueRecovered = attritionRecovered * this.ATTRITION_PT; // ₱M of lifetime revenue
            const committed = Math.max(1, ds.internalSpent + ds.adSpent + ds.serviceSpent);
            ds.roi = Math.round((valueRecovered / committed) * 100) / 100;

            // Budget tracking.
            ds.spent = Math.round((ds.internalSpent + ds.adSpent + ds.serviceSpent) * 10) / 10;
            ds.overBudget = ds.spent > this.BUDGET;

            ds.satHistory.push(ds.sat);
            ds.brandHistory.push(ds.brand);
            ds.gapHistory.push(ds.gap);

            // ---- Persist the composite where the gradebook / reporting layer reads it. ----
            // express_resolveDomainScore() reads domainState.performance.overallScore first,
            // then a top-level score; express_extractHistory() reads the same per period.
            // Without this the instructor Results show "—", the per-period sparkline is empty
            // and the gametype-20 (record_grade / AGS) post-back sends 0.
            const _score = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = _score;
            ds.score = _score;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                sat: ds.sat,
                satDelta: Math.round(satDelta * 10) / 10,
                gap: ds.gap,
                gapDelta: Math.round(gapDelta * 100) / 100,
                brand: ds.brand,
                brandDelta: Math.round(brandDelta * 10) / 10,
                roi: ds.roi,
                engagement: ds.engagement,
                promise: ds.promise,
                actualTime: ds.actualTime,
                spent: ds.spent,
                overPromiseRun: ds.overPromiseRun,
                adFixRun: ds.adFixRun,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                score: _score,
                overallScore: _score
            };
        }

        _satClass(v) {
            if (v < this.FLOOR_SAT) return `danger`;
            if (v < this.TARGET_SAT) return `warn`;
            return `good`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`satDisplay`, `domainState.sat`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.servesells-card-sat`);
                if (card) {
                    card.classList.toggle(`servesells-sat-danger`, n < self.FLOOR_SAT);
                    card.classList.toggle(`servesells-sat-warn`, n >= self.FLOOR_SAT && n < self.TARGET_SAT);
                    card.classList.toggle(`servesells-sat-good`, n >= self.TARGET_SAT);
                }
                return `${self._fmtNum(n, 0)}%`;
            });

            uiManager.bind(`gapDisplay`, `domainState.gap`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.servesells-card-gap`);
                if (card) {
                    card.classList.toggle(`servesells-gap-good`, n <= 1.0);
                    card.classList.toggle(`servesells-gap-bad`, n >= 1.6);
                }
                return self._fmtNum(n, 1);
            });

            uiManager.bind(`brandDisplay`, `domainState.brand`, (v) => `${self._fmtNum(Number(v), 0)}`);

            uiManager.bind(`roiDisplay`, `domainState.roi`, (v) => `${self._fmtNum(Number(v), 2)}×`);

            uiManager.bind(`budgetDisplay`, `domainState.spent`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.servesells-budget-bar`);
                if (bar) {
                    bar.classList.toggle(`servesells-budget-over`, n > self.BUDGET);
                    bar.classList.toggle(`servesells-budget-full`, n >= self.BUDGET * 0.85 && n <= self.BUDGET);
                }
                return `₱${self._fmtNum(n, 0)}M / ₱${self.BUDGET}M`;
            });

            // Inaction slider readout.
            const ia = document.getElementById(`inactionInput`);
            const iaReadout = document.getElementById(`inactionReadout`);
            if (ia && iaReadout) {
                iaReadout.textContent = ia.value;
                ia.addEventListener(`input`, function() { iaReadout.textContent = ia.value; });
            }

            // Accessibility: mirror each control's visible (data-i18n) prompt onto the
            // control via aria-label — the prompts are separate elements (no <label for>),
            // so a screen reader would otherwise announce an unlabeled <select>. t() keeps
            // the label correct in each language.
            const tA = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const ariaMap = {
                rootInput: `r1_root_label`, dimInput: `r1_dim_label`, symptomInput: `r1_symptom_label`,
                inactionInput: `r1_inaction_label`, slaInput: `r2_sla_label`, empowerInput: `r2_empower_label`,
                cultureInput: `r2_culture_label`, internalBudgetInput: `r2_internalbudget_label`,
                promiseInput: `r3_promise_label`, advertisingInput: `r3_advertising_label`,
                serviceInput: `r3_service_label`, internalTopupInput: `r3_topup_label`,
                defenseInput: `r4_defense_label`, shockInput: `r4_shock_label`,
                indicatorInput: `r4_indicator_label`, holdInput: `r4_hold_label`
            };
            Object.keys(ariaMap).forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.setAttribute(`aria-label`, tA(ariaMap[id]));
            });
        }

        _fmtNum(v, decimals) {
            // Locale-aware number: en "1.8", es "1,8".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(decimals);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

        getChartConfig() {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            return {
                serveChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: t(`chart_ds_sat`),
                                data: [],
                                borderColor: `#15786e`,
                                backgroundColor: `rgba(21,120,110,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#15786e`,
                                yAxisID: `y`
                            },
                            {
                                label: t(`chart_ds_brand`),
                                data: [],
                                borderColor: `#2b6cb0`,
                                backgroundColor: `rgba(43,108,176,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2b6cb0`,
                                yAxisID: `y`
                            },
                            {
                                label: t(`chart_ds_gap`),
                                data: [],
                                borderColor: `#c2792c`,
                                backgroundColor: `rgba(194,121,44,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#c2792c`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#44586a`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#76889a` }, grid: { color: `rgba(29,39,51,0.06)` },
                                title: { display: true, text: `0–100`, color: `#76889a` }
                            },
                            x: {
                                ticks: { color: `#76889a` }, grid: { color: `rgba(29,39,51,0.04)` },
                                title: { display: true, text: `Round`, color: `#76889a` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.satHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Gap is 0–3 — scale ×20 to share the 0–100 axis with the percentages and the index.
            const gapScaled = ds.gapHistory.map((v) => Math.round(v * 20));
            return {
                serveChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.satHistory.map((v) => Math.round(v * 10) / 10) },
                        { data: ds.brandHistory.map((v) => Math.round(v)) },
                        { data: gapScaled }
                    ]
                }
            };
        }

        // ---- Composite score — single source of truth. ----
        // Carries the VERBATIM v1.0.0 getPerformanceSummary formula so the score
        // persisted every period equals the completion composite by construction.
        _composite(ds) {
            const sat   = Math.round(ds.sat * 10) / 10;
            const brand = Math.round(ds.brand);
            const gap   = Math.round(ds.gap * 100) / 100;
            const roi   = Math.round(ds.roi * 100) / 100;
            const gapScore = Math.max(0, (3 - gap) / 3) * 100;
            const roiScore = Math.min(100, roi * 60);
            return Math.round(sat * 0.40 + brand * 0.22 + gapScore * 0.22 + roiScore * 0.16);
        }

        // Map the (stable, English) performance tier id to its localized label.
        _gradeLabel(performance) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const map = {
                'Service Brand Restored': `grade_restored`,
                'Target Hit':             `grade_target`,
                'Advertised the Fix':     `grade_adfix`,
                'Price-War Pivot':        `grade_pivot`,
                'Mixed Recovery':         `grade_mixed`,
                'Brand at Risk':          `grade_atrisk`
            };
            return t(map[performance] || `grade_atrisk`);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const sat = Math.round(ds.sat * 10) / 10;
            const brand = Math.round(ds.brand);
            const gap = Math.round(ds.gap * 100) / 100;
            const roi = Math.round(ds.roi * 100) / 100;

            const hitTarget = sat >= this.TARGET_SAT;
            const aboveFloor = sat >= this.FLOOR_SAT;
            const gapClosed = gap <= 1.0;
            const brandRecovered = brand >= this.START_BRAND;
            const internalLed = ds.internalSpent >= 100 && !ds.adFixRun;

            // Composite — computed by _composite(), the SAME helper persisted to
            // domainState.performance.overallScore each period, so the completion score
            // equals the last per-period score by construction.
            const composite = this._composite(ds);

            let pattern = `mixed`;
            if (ds.adFixRun || ds.overPromiseRun) pattern = `adfix`;
            else if (internalLed && gapClosed && hitTarget) pattern = `orientation`;
            else if (ds.misdiagnosed && !internalLed) pattern = `misdiagnosed`;

            let performance = `Brand at Risk`;
            if (hitTarget && gapClosed && brandRecovered && internalLed && composite >= 73) performance = `Service Brand Restored`;
            else if (hitTarget && internalLed && !ds.adFixRun) performance = `Target Hit`;
            else if (ds.adFixRun && sat < this.TARGET_SAT) performance = `Advertised the Fix`;
            else if (!aboveFloor) performance = `Price-War Pivot`;
            else if (composite >= 58) performance = `Mixed Recovery`;

            const insights = [];
            if (pattern === `orientation`) insights.push(window.mySimulation.t(`insight_orientation`));
            else if (pattern === `adfix`) insights.push(window.mySimulation.t(`insight_adfix`));
            else if (pattern === `misdiagnosed`) insights.push(window.mySimulation.t(`insight_misdiagnosed`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.overPromiseRun) insights.push(window.mySimulation.t(`insight_overpromise`));
            if (!aboveFloor) insights.push(window.mySimulation.t(`insight_floor`));
            if (ds.slaUnresourced) insights.push(window.mySimulation.t(`insight_sla`));
            if (!gapClosed) insights.push(window.mySimulation.t(`insight_gap_open`));
            if (hitTarget && !brandRecovered) insights.push(window.mySimulation.t(`insight_brand_lag`));
            if (ds.overBudget) insights.push(window.mySimulation.t(`insight_overbudget`));

            return {
                sat: sat,
                brand: brand,
                gap: gap,
                roi: roi,
                hitTarget: hitTarget,
                aboveFloor: aboveFloor,
                gapClosed: gapClosed,
                brandRecovered: brandRecovered,
                internalLed: internalLed,
                pattern: pattern,
                composite: composite,
                performance: performance,
                performanceLabel: this._gradeLabel(performance),
                insights: insights
            };
        }

        // Localized completion debrief — the base class default only prints
        // "You completed N periods", discarding the composite, tier, targets,
        // KPIs and insights this sim computes. Rendered into #usf-completion-content.
        formatCompletionMessage(summary) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const s = summary || {};
            const composite = Number.isFinite(s.composite) ? s.composite : this._composite(window.mySimulation.state.domainState);
            const verdict = s.performanceLabel || this._gradeLabel(s.performance || `Brand at Risk`);
            const top = (s.performance === `Service Brand Restored`);
            const fmt = this._fmtNum.bind(this);
            const chip = (ok, label) =>
                `<span class="sts-cm-chip ${ok ? `sts-cm-chip-ok` : `sts-cm-chip-no`}">${ok ? `✓` : `✗`} ${label}</span>`;
            const kpi = (label, value, sub) =>
                `<div class="sts-cm-kpi"><div class="sts-cm-kpi-val">${value}</div>` +
                `<div class="sts-cm-kpi-lbl">${label}</div>` + (sub ? `<div class="sts-cm-kpi-sub">${sub}</div>` : ``) + `</div>`;
            const chips = [
                chip(!!s.hitTarget,      t(`cm_t_target`)),
                chip(!!s.gapClosed,      t(`cm_t_gap`)),
                chip(!!s.brandRecovered, t(`cm_t_brand`)),
                chip(!!s.internalLed,    t(`cm_t_internal`)),
                chip(!!s.aboveFloor,     t(`cm_t_floor`))
            ].join(``);
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const insightsHtml = insights.length
                ? `<div class="sts-cm-h">${t(`cm_insights_h`)}</div><ul class="sts-cm-insights">` +
                  insights.map((x) => `<li>${x}</li>`).join(``) + `</ul>` : ``;
            return `
                <div class="sts-cm ${top ? `sts-cm-top` : ``}">
                    <div class="sts-cm-verdict">
                        <div class="sts-cm-score"><span class="sts-cm-score-num">${composite}</span><span class="sts-cm-score-den">/100</span></div>
                        <div class="sts-cm-verdict-txt">
                            <div class="sts-cm-badge">${verdict}</div>
                            <div class="sts-cm-sub">${t(`cm_periods_pre`)} ${s.totalPeriods || 4} ${t(`cm_periods_post`)}</div>
                        </div>
                    </div>
                    <div class="sts-cm-h">${t(`cm_targets_h`)}</div>
                    <div class="sts-cm-chips">${chips}</div>
                    <div class="sts-cm-h">${t(`cm_kpis_h`)}</div>
                    <div class="sts-cm-kpis">
                        ${kpi(t(`sat_label`), fmt(Number(s.sat) || 0, 0) + `%`, t(`cm_target`) + ` 75%`)}
                        ${kpi(t(`gap_label`), fmt(Number(s.gap) || 0, 1), t(`cm_target`) + ` ≤1.0`)}
                        ${kpi(t(`brand_label`), Math.round(Number(s.brand) || 0), t(`cm_from`) + ` 58`)}
                        ${kpi(t(`roi_label`), fmt(Number(s.roi) || 0, 2) + `×`, `ROI`)}
                    </div>
                    ${insightsHtml}
                </div>
            `;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.sat < this.FLOOR_SAT) return window.mySimulation.t(`hint_floor`);
            if (ds.overPromiseRun) return window.mySimulation.t(`hint_overpromise`);
            if (ds.adFixRun) return window.mySimulation.t(`hint_adfix`);
            if (ds.misdiagnosed && state.currentPeriod < 3) return window.mySimulation.t(`hint_misdiagnosed`);
            if (ds.internalSpent < 100 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_internal`);
            if (ds.sat >= this.TARGET_SAT && ds.gap <= 1.0) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.sat`, label: `Satisfaction`, i18nKey: `col_sat`, formatter: (v) => `${self._fmtNum(Number(v), 0)}%` },
                { key: `results.gap`, label: `Gap`, i18nKey: `col_gap`, formatter: (v) => self._fmtNum(Number(v), 1) },
                { key: `results.brand`, label: `Brand`, i18nKey: `col_brand`, formatter: (v) => `${Math.round(Number(v))}` },
                { key: `results.roi`, label: `ROI`, i18nKey: `col_roi`, formatter: (v) => `${self._fmtNum(Number(v), 2)}×` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

